"""Original-specimen and structural controls; generated bytes stay in scratch.

Usage: python3 check.py ORIGINAL_EXE EXTRACTED_STAGE SCRATCH_DIR
No Windows executable is launched. CLEAVE may override the analysis engine.
"""
import concurrent.futures
import json
import os
from pathlib import Path
import struct
import subprocess
import sys

original, stage, scratch = map(Path, sys.argv[1:])
scratch.mkdir(parents=True, exist_ok=True)
repo = Path(__file__).resolve().parents[3]
exe = os.environ.get('CLEAVE', 'cleave')
ids = {
    'map': 'objectives/anti-static/pack/manual-map::x64-debugger-gated-overlay-image-loader',
    'syscall': 'objectives/evasion/anti-av/syscall::extracted-ssn-indirect-trampoline-bypass',
    'peb': 'objectives/evasion/process/loader::gated-overlay-loader-peb-imagebase-substitution',
    'sleep': 'objectives/evasion/process/loader::concealed-image-loader-xor-masked-wait',
    'debug': 'objectives/anti-analysis/debugger-detect/check::peb-being-debugged-byte-branch',
    'hash': 'objectives/anti-static/obfuscation/imports/api-hashing::x64-xorshift-export-api-concealment',
    'vm': 'objectives/anti-static/obfuscation/string/encrypt::xor-concealed-vm-agent-catalog',
    'chacha': 'micro-behaviors/crypto/symmetric/stream/chacha::x64-indexed-chacha-column-rounds',
    'constant': 'metadata/binary/instruction/operand::inverse-golden-ratio-imul',
    'tray': 'micro-behaviors/process/info/name::vm-guest-tray-process-name',
    'dll': 'micro-behaviors/os/module/load::advapi32-dll-reference',
    'tea': 'micro-behaviors/crypto/symmetric/xxtea::x86-tea-decrypt-round',
    'browser': 'objectives/credential-access/browser/multi-target::encrypted-native-multi-browser-collector',
}
old = {
    'micro-behaviors/crypto/symmetric/xxtea::xxtea-phi2-delta',
    'metadata/binary/symbols/imports::imports-advapi32-dll',
    'objectives/anti-analysis/vm-detect/artifact::vboxtray-process-name',
}
cases = []
b = original.read_bytes()
all_hostile = {'map', 'syscall', 'peb', 'sleep'}

def add(name, data, present=(), absent=(), hostile=None):
    p = scratch / (name + '.exe')
    p.write_bytes(data)
    cases.append((name, p, set(present), set(absent), hostile))

def patch_at(pattern, relative, value):
    pattern = bytes.fromhex(pattern)
    assert b.count(pattern) == 1, (pattern.hex(), b.count(pattern))
    q = bytearray(b)
    q[b.index(pattern) + relative] = value
    return q

add('renamed-original', b, all_hostile | {'debug', 'hash', 'vm', 'chacha', 'constant', 'tray', 'dll'})
add('debug-field-is-not-beingdebugged', patch_at('65 48 8b 04 25 60 00 00 00 40 38 70 02', 12, 3),
    {'syscall'}, {'debug', 'map', 'peb', 'sleep'})
add('entry-handoff-removed', patch_at('48 03 c7 ff d0 33 c0', 3, 0x90),
    {'syscall'}, {'map', 'peb', 'sleep'})
add('ssn-prologue-is-not-native', patch_at('41 8b 00 3d 4c 8b d1 b8 75 05', 4, 0x4d),
    all_hostile - {'syscall'}, {'syscall'})
add('gadget-is-not-syscall', patch_at('ba 0f 05 00 00 8b d9 48 03 df', 2, 6),
    all_hostile - {'syscall'}, {'syscall'})
add('constructed-jump-is-not-indirect', patch_at('c6 40 0a 25 c7 40 0b', 3, 0x24),
    all_hostile - {'syscall'}, {'syscall'})
add('peb-store-is-not-imagebase', patch_at('48 89 78 10 48 8b 05', 3, 0x18),
    all_hostile - {'peb'}, {'peb'})
add('mask-loop-xor-removed', patch_at('83 e0 0f 32 4c 05 f0 88 0c 1a', 3, 0x30),
    all_hostile - {'sleep'}, {'sleep'})
add('hash-mask-value-varies', patch_at('81 f2 83 81 52 49 41 33 c8', 2, 0x42),
    all_hostile | {'hash'})
# Repeated process-name references still do not establish a VM probe.
# Genuine PE32 fixture, two sections, no import directory or staged payload.
def pe32(code, data=b''):
    q = bytearray(0x600)
    q[:2] = b'MZ'
    struct.pack_into('<I', q, 0x3c, 0x80)
    q[0x80:0x84] = b'PE\0\0'
    struct.pack_into('<HHIIIHH', q, 0x84, 0x14c, 2, 0, 0, 0, 0xe0, 0x102)
    o = 0x98
    struct.pack_into('<H', q, o, 0x10b)
    struct.pack_into('<III', q, o + 16, 0x1000, 0x1000, 0x2000)
    struct.pack_into('<III', q, o + 28, 0x400000, 0x1000, 0x200)
    struct.pack_into('<HH', q, o + 40, 6, 0)
    struct.pack_into('<HH', q, o + 48, 6, 0)
    struct.pack_into('<II', q, o + 56, 0x3000, 0x200)
    struct.pack_into('<H', q, o + 68, 2)
    struct.pack_into('<IIIIII', q, o + 72, 0x100000, 0x1000, 0x100000, 0x1000, 0, 16)
    for s, name, rva, off, flags in [(0x178, b'.text', 0x1000, 0x200, 0x60000020),
                                     (0x1a0, b'.rdata', 0x2000, 0x400, 0x40000040)]:
        struct.pack_into('<8sIIIIIIHHI', q, s, name, 0x200, rva, 0x200, off, 0, 0, 0, 0, flags)
    q[0x200:0x200 + len(code)] = code
    q[0x400:0x400 + len(data)] = data
    return q
add('constant-and-library-reference-only', pe32(bytes.fromhex('69 c0 47 86 c8 61 c3'),
    b'ADVAPI32.dll\0VBoxTray\0vmwaretray\0'), {'constant', 'tray', 'dll'}, all_hostile | {'debug', 'vm', 'tea'}, 0)
add('original-x86-peb-positive', pe32(bytes.fromhex('64 a1 30 00 00 00 80 78 02 00 75 01 c3')), {'debug'}, all_hostile, 0)
add('x86-peb-near-miss', pe32(bytes.fromhex('64 a1 30 00 00 00 80 78 03 00 75 01 c3')), (), {'debug'} | all_hostile, 0)
add('retained-tea-round', pe32(bytes.fromhex('8b c1 c1 e0 04 03 c2 8b d1 03 4c 24 04 c1 ea 05 03 54 24 08 33 c2 33 c1 c3')),
    {'tea'}, all_hostile, 0)
# The extracted native collection routine is an independent positive fixture.
cases.append(('extracted-stage', stage, {'browser'}, all_hostile, None))

def check(case):
    name, path, present, absent, hostile_count = case
    p = subprocess.run([exe, '--traits-dir', str(repo), '--format', 'json', str(path)],
                       capture_output=True, text=True)
    assert p.returncode == 0, (name, p.stderr)
    d = json.loads(p.stdout)
    f = d['files'][0]
    ts = {t['id']: t['crit'] for t in f['traits']}
    assert {ids[x] for x in present} <= ts.keys(), (name, 'missing', {ids[x] for x in present} - ts.keys())
    assert not {ids[x] for x in absent} & ts.keys(), (name, 'unexpected', {ids[x] for x in absent} & ts.keys())
    assert not old & ts.keys(), (name, 'misleading retired claims', old & ts.keys())
    if hostile_count is not None:
        assert sum(x == 5 for x in ts.values()) == hostile_count, (name, 'hostile', ts)
    return {'case': name, 'passed': True, 'hostile': sum(x == 5 for x in ts.values()),
            'suspicious': sum(x == 4 for x in ts.values())}

with concurrent.futures.ThreadPoolExecutor(max_workers=4) as pool:
    results = list(pool.map(check, cases))
print(json.dumps({'cases': results}, indent=2))
